package driver

import (
	"math"
	"time"
)

const (
	farePerMinute = 1.50
	minimumFare   = 3.50
)

// computeFare returns the fare in dollars for a trip with the given ETA,
// rounded to the nearest cent.
func computeFare(eta time.Duration) float64 {
	fare := math.Max(eta.Minutes()*farePerMinute, minimumFare)
	return math.Round(fare*100) / 100
}
EOF
