package driver

import (
	"testing"
	"time"
)

func TestComputeFare(t *testing.T) {
	tests := []struct {
		name string
		eta  time.Duration
		want float64
	}{
		{"zero uses minimum", 0, 3.50},
		{"negative uses minimum", -5 * time.Minute, 3.50},
		{"fast route uses minimum", time.Second, 3.50},
		{"just under minimum", 2 * time.Minute, 3.50},
		{"exactly at minimum", 140 * time.Second, 3.50},
		{"whole minutes", 10 * time.Minute, 15.00},
		{"fractional minutes", 12*time.Minute + 30*time.Second, 18.75},
		{"rounds to cents", 7*time.Minute + 7*time.Second, 10.68},
		{"long trip", 45 * time.Minute, 67.50},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := computeFare(tt.eta); got != tt.want {
				t.Errorf("computeFare(%v) = %v, want %v", tt.eta, got, tt.want)
			}
		})
	}
}
