package location

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/go-sql-driver/mysql"
	"go.opentelemetry.io/otel/attribute"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
	"go.opentelemetry.io/otel/trace"
)

const rideHistoryTableSchema = `
CREATE TABLE IF NOT EXISTS ride_history
(
    id bigint unsigned NOT NULL AUTO_INCREMENT,
    pickup_location varchar(255) NOT NULL,
    dropoff_location varchar(255) NOT NULL,
    request_time datetime(3) NOT NULL,
    driver_plate varchar(64) NULL,
    fare decimal(10,2) NULL,

    PRIMARY KEY (id),
    KEY request_time (request_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
`

const rideHistoryColumns = "id, pickup_location, dropoff_location, request_time, driver_plate, fare"

// errRideNotFound is returned when a ride history entry doesn't exist.
var errRideNotFound = errors.New("ride history entry not found")

// ensureRideHistoryTable creates the ride_history table if it doesn't exist.
//
// It is kept apart from setupDB, which also seeds the locations table: the
// ride_history table must be creatable on databases that already have
// locations (and their seed data) but were created before ride history existed.
func (d *database) ensureRideHistoryTable() error {
	_, err := d.db.Exec(rideHistoryTableSchema)
	return err
}

// withRideHistoryTable runs fn, creating the ride_history table and retrying
// once if the table is missing.
func (d *database) withRideHistoryTable(fn func() error) error {
	err := fn()
	if mysqlErr, ok := err.(*mysql.MySQLError); ok && mysqlErr.Number == 1146 {
		if err := d.ensureRideHistoryTable(); err != nil {
			return err
		}
		return fn()
	}
	return err
}

func (d *database) startRideHistorySpan(ctx context.Context, query string) trace.Span {
	_, span := d.tracer.Start(ctx, "SQL "+strings.Fields(query)[0], trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.PeerServiceKey.String("mysql"),
		attribute.Key("sql.query").String(query),
	)
	return span
}

// ListRideHistory returns the most recent rides, newest first, along with the
// total number of rides stored.
func (d *database) ListRideHistory(ctx context.Context, limit int) (*RideHistoryList, error) {
	query := "SELECT " + rideHistoryColumns + " FROM ride_history ORDER BY request_time DESC, id DESC LIMIT ?"
	countQuery := "SELECT COUNT(*) FROM ride_history"
	span := d.startRideHistorySpan(ctx, query)
	defer span.End()

	list := &RideHistoryList{Rides: []RideHistoryEntry{}}
	err := d.withRideHistoryTable(func() error {
		list.Rides = list.Rides[:0]
		rows, err := d.db.QueryContext(ctx, query, limit)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			e, err := scanRide(rows)
			if err != nil {
				return err
			}
			list.Rides = append(list.Rides, *e)
		}
		if err := rows.Err(); err != nil {
			return err
		}
		return d.db.QueryRowContext(ctx, countQuery).Scan(&list.Total)
	})
	if err != nil {
		return nil, err
	}
	return list, nil
}

// CreateRideHistory stores a new ride and returns it with its ID populated.
func (d *database) CreateRideHistory(ctx context.Context, entry *RideHistoryEntry) (*RideHistoryEntry, error) {
	query := "INSERT INTO ride_history (pickup_location, dropoff_location, request_time) VALUES (?, ?, ?)"
	span := d.startRideHistorySpan(ctx, query)
	defer span.End()

	// the column has millisecond precision
	requestTime := entry.RequestTime.UTC().Truncate(time.Millisecond)
	var id int64
	err := d.withRideHistoryTable(func() error {
		res, err := d.db.ExecContext(ctx, query, entry.PickupLocation, entry.DropoffLocation, requestTime)
		if err != nil {
			return err
		}
		id, err = res.LastInsertId()
		return err
	})
	if err != nil {
		return nil, err
	}
	created := *entry
	created.ID = id
	created.RequestTime = requestTime
	return &created, nil
}

// UpdateRideHistory sets the driver plate and/or fare of an existing ride and
// returns the updated ride. It returns errRideNotFound if the ride doesn't exist.
func (d *database) UpdateRideHistory(ctx context.Context, update *RideHistoryUpdate) (*RideHistoryEntry, error) {
	var (
		sets []string
		args []interface{}
	)
	if update.DriverPlate != nil {
		sets = append(sets, "driver_plate = ?")
		args = append(args, *update.DriverPlate)
	}
	if update.Fare != nil {
		sets = append(sets, "fare = ?")
		args = append(args, *update.Fare)
	}
	if len(sets) == 0 {
		return nil, errors.New("nothing to update")
	}
	args = append(args, update.ID)
	query := "UPDATE ride_history SET " + strings.Join(sets, ", ") + " WHERE id = ?"
	span := d.startRideHistorySpan(ctx, query)
	defer span.End()

	var entry *RideHistoryEntry
	err := d.withRideHistoryTable(func() error {
		// rows affected is 0 both when the ride doesn't exist and when the values
		// are unchanged, so the SELECT below decides whether the ride exists.
		if _, err := d.db.ExecContext(ctx, query, args...); err != nil {
			return err
		}
		row := d.db.QueryRowContext(ctx, "SELECT "+rideHistoryColumns+" FROM ride_history WHERE id = ?", update.ID)
		var err error
		entry, err = scanRide(row)
		if errors.Is(err, sql.ErrNoRows) {
			return errRideNotFound
		}
		return err
	})
	if err != nil {
		return nil, err
	}
	return entry, nil
}

type rowScanner interface {
	Scan(dest ...interface{}) error
}

func scanRide(row rowScanner) (*RideHistoryEntry, error) {
	var (
		e     RideHistoryEntry
		plate sql.NullString
		fare  sql.NullFloat64
	)
	if err := row.Scan(&e.ID, &e.PickupLocation, &e.DropoffLocation, &e.RequestTime, &plate, &fare); err != nil {
		return nil, err
	}
	if plate.Valid {
		e.DriverPlate = &plate.String
	}
	if fare.Valid {
		e.Fare = &fare.Float64
	}
	return &e, nil
}

func (e *RideHistoryEntry) String() string {
	return fmt.Sprintf("ride %d: %s -> %s", e.ID, e.PickupLocation, e.DropoffLocation)
}
