)

const (
	defaultRideHistoryLimit = 50
	maxRideHistoryLimit     = 1000
	maxRideHistoryBody      = 1 << 20

	maxLocationNameLen = 255
	maxDriverPlateLen  = 64
	maxFare            = 99999999.99 // decimal(10,2)
)

func (s *Server) listRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	limit := defaultRideHistoryLimit
	if v := r.URL.Query().Get("limit"); v != "" {
		var err error
		limit, err = strconv.Atoi(v)
		if err != nil || limit < 1 || limit > maxRideHistoryLimit {
			err = errors.New("parameter 'limit' must be an integer between 1 and " + strconv.Itoa(maxRideHistoryLimit))
			httperr.HandleError(w, err, http.StatusBadRequest)
			s.logger.For(ctx).Error("bad request", zap.Error(err))
			return
		}
	}

	list, err := s.database.ListRideHistory(ctx, limit)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot get ride history", zap.Error(err))
		return
	}
	s.writeJSON(w, r, http.StatusOK, list)
}

func (s *Server) createRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	var entry RideHistoryEntry
	err := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxRideHistoryBody)).Decode(&entry)
	if err == nil {
		err = validateNewRide(&entry)
	}
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}
	if entry.RequestTime.IsZero() {
		entry.RequestTime = time.Now()
	}
	// a ride starts without a driver, whatever the client sent
	entry.DriverPlate, entry.Fare = nil, nil

	created, err := s.database.CreateRideHistory(ctx, &entry)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}
	s.writeJSON(w, r, http.StatusCreated, created)
}

func (s *Server) updateRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	var update RideHistoryUpdate
	err := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxRideHistoryBody)).Decode(&update)
	if err == nil {
		err = validateRideUpdate(&update)
	}
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	updated, err := s.database.UpdateRideHistory(ctx, &update)
	if errors.Is(err, errRideNotFound) {
		httperr.HandleError(w, err, http.StatusNotFound)
		s.logger.For(ctx).Error("ride not found", zap.Int64("id", update.ID))
		return
	}
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}
	s.writeJSON(w, r, http.StatusOK, updated)
}

func (s *Server) writeJSON(w http.ResponseWriter, r *http.Request, status int, v interface{}) {
	data, err := json.Marshal(v)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(r.Context()).Error("cannot marshal response", zap.Error(err))
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(data)
}

func validateNewRide(e *RideHistoryEntry) error {
	e.PickupLocation = strings.TrimSpace(e.PickupLocation)
	e.DropoffLocation = strings.TrimSpace(e.DropoffLocation)
	if e.PickupLocation == "" || e.DropoffLocation == "" {
		return errors.New("'pickupLocation' and 'dropoffLocation' are required")
	}
	if utf8.RuneCountInString(e.PickupLocation) > maxLocationNameLen ||
		utf8.RuneCountInString(e.DropoffLocation) > maxLocationNameLen {
		return errors.New("location names are limited to 255 characters")
	}
	return nil
}

func validateRideUpdate(u *RideHistoryUpdate) error {
	if u.ID <= 0 {
		return errors.New("'id' is required")
	}
	if u.DriverPlate == nil && u.Fare == nil {
		return errors.New("at least one of 'driverPlate' and 'fare' is required")
	}
	if u.DriverPlate != nil {
		plate := strings.TrimSpace(*u.DriverPlate)
		if plate == "" || utf8.RuneCountInString(plate) > maxDriverPlateLen {
			return errors.New("'driverPlate' must be between 1 and 64 characters")
		}
		u.DriverPlate = &plate
	}
	if u.Fare != nil {
		if math.IsNaN(*u.Fare) || *u.Fare < 0 || *u.Fare > maxFare {
			return errors.New("'fare' must be between 0 and 99999999.99")
		}
		fare := math.Round(*u.Fare*100) / 100
		u.Fare = &fare
	}
	return nil
}
