package frontend

import (
	"context"
	"io"
	"net/http"

	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/httperr"
)

// rideHistoryForwarder forwards ride history requests to the location service.
type rideHistoryForwarder interface {
	ForwardRideHistory(ctx context.Context, method, rawQuery string, body io.Reader) (*http.Response, error)
}

// proxyRideHistory proxies GET, POST and PATCH ride history requests to the
// location service, relaying its status code and response body unchanged.
func (s *Server) proxyRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	var body io.Reader
	if r.Method != http.MethodGet {
		body = http.MaxBytesReader(w, r.Body, 1<<20)
	}
	resp, err := s.rideHistory.ForwardRideHistory(ctx, r.Method, r.URL.RawQuery, body)
	if httperr.HandleError(w, err, http.StatusBadGateway) {
		s.logger.For(ctx).Error("couldn't forward ride history request", zap.Error(err))
		return
	}
	defer resp.Body.Close()

	if ct := resp.Header.Get("Content-Type"); ct != "" {
		w.Header().Set("Content-Type", ct)
	}
	w.WriteHeader(resp.StatusCode)
	if _, err := io.Copy(w, resp.Body); err != nil {
		s.logger.For(ctx).Error("couldn't relay ride history response", zap.Error(err))
	}
}
EOF
