package location

import (
	"strings"
	"testing"
)

func ptr[T any](v T) *T { return &v }

func TestValidateNewRide(t *testing.T) {
	tests := []struct {
		name    string
		entry   RideHistoryEntry
		wantErr bool
	}{
		{"valid", RideHistoryEntry{PickupLocation: "My Home", DropoffLocation: "Trom Chocolatier"}, false},
		{"missing pickup", RideHistoryEntry{DropoffLocation: "Trom Chocolatier"}, true},
		{"blank dropoff", RideHistoryEntry{PickupLocation: "My Home", DropoffLocation: "  "}, true},
		{"name too long", RideHistoryEntry{PickupLocation: strings.Repeat("a", 256), DropoffLocation: "b"}, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if err := validateNewRide(&tt.entry); (err != nil) != tt.wantErr {
				t.Errorf("validateNewRide() error = %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

func TestValidateRideUpdate(t *testing.T) {
	tests := []struct {
		name    string
		update  RideHistoryUpdate
		wantErr bool
	}{
		{"valid", RideHistoryUpdate{ID: 1, DriverPlate: ptr("T712345C"), Fare: ptr(18.75)}, false},
		{"plate only", RideHistoryUpdate{ID: 1, DriverPlate: ptr("T712345C")}, false},
		{"fare only", RideHistoryUpdate{ID: 1, Fare: ptr(3.5)}, false},
		{"zero fare", RideHistoryUpdate{ID: 1, Fare: ptr(0.0)}, false},
		{"missing id", RideHistoryUpdate{DriverPlate: ptr("T712345C")}, true},
		{"nothing to update", RideHistoryUpdate{ID: 1}, true},
		{"blank plate", RideHistoryUpdate{ID: 1, DriverPlate: ptr(" ")}, true},
		{"negative fare", RideHistoryUpdate{ID: 1, Fare: ptr(-1.0)}, true},
		{"fare too large", RideHistoryUpdate{ID: 1, Fare: ptr(1e9)}, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if err := validateRideUpdate(&tt.update); (err != nil) != tt.wantErr {
				t.Errorf("validateRideUpdate() error = %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

func TestValidateRideUpdateRoundsFare(t *testing.T) {
	u := RideHistoryUpdate{ID: 1, Fare: ptr(10.675000001)}
	if err := validateRideUpdate(&u); err != nil {
		t.Fatal(err)
	}
	if *u.Fare != 10.68 {
		t.Errorf("fare = %v, want 10.68", *u.Fare)
	}
}
EOF
cat > frontend/ride_history_test.go <<'EOF'
package frontend

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/signadot/hotrod/pkg/log"
	"go.uber.org/zap"
)

type fakeForwarder struct {
	method, query, body string
	resp                *http.Response
}

func (f *fakeForwarder) ForwardRideHistory(_ context.Context, method, rawQuery string, body io.Reader) (*http.Response, error) {
	f.method, f.query = method, rawQuery
	if body != nil {
		b, _ := io.ReadAll(body)
		f.body = string(b)
	}
	return f.resp, nil
}

func TestProxyRideHistory(t *testing.T) {
	fwd := &fakeForwarder{resp: &http.Response{
		StatusCode: http.StatusNotFound,
		Header:     http.Header{"Content-Type": []string{"text/plain"}},
		Body:       io.NopCloser(strings.NewReader("ride history entry not found")),
	}}
	s := &Server{logger: log.NewFactory(zap.NewNop()), rideHistory: fwd}

	req := httptest.NewRequest(http.MethodPatch, "/ride-history?x=1", strings.NewReader(`{"id":7}`))
	rec := httptest.NewRecorder()
	s.proxyRideHistory(rec, req)

	if fwd.method != http.MethodPatch || fwd.query != "x=1" || fwd.body != `{"id":7}` {
		t.Errorf("forwarded %q %q %q", fwd.method, fwd.query, fwd.body)
	}
	if rec.Code != http.StatusNotFound || rec.Body.String() != "ride history entry not found" {
		t.Errorf("got %d %q, want the location service response relayed", rec.Code, rec.Body.String())
	}
	if ct := rec.Header().Get("Content-Type"); ct != "text/plain" {
		t.Errorf("content type = %q", ct)
	}
}
EOF
