package frontend

import (
	"context"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/signadot/hotrod/pkg/log"
	"go.uber.org/zap"
)

type fakeForwarder struct {
	method, query, body string
	resp                *http.Response
}

func (f *fakeForwarder) ForwardRideHistory(_ context.Context, method, rawQuery string, body io.Reader) (*http.Response, error) {
	f.method, f.query = method, rawQuery
	if body != nil {
		b, _ := io.ReadAll(body)
		f.body = string(b)
	}
	return f.resp, nil
}

func TestProxyRideHistory(t *testing.T) {
	fwd := &fakeForwarder{resp: &http.Response{
		StatusCode: http.StatusNotFound,
		Header:     http.Header{"Content-Type": []string{"text/plain"}},
		Body:       io.NopCloser(strings.NewReader("ride history entry not found")),
	}}
	s := &Server{logger: log.NewFactory(zap.NewNop()), rideHistory: fwd}

	req := httptest.NewRequest(http.MethodPatch, "/ride-history?x=1", strings.NewReader(`{"id":7}`))
	rec := httptest.NewRecorder()
	s.proxyRideHistory(rec, req)

	if fwd.method != http.MethodPatch || fwd.query != "x=1" || fwd.body != `{"id":7}` {
		t.Errorf("forwarded %q %q %q", fwd.method, fwd.query, fwd.body)
	}
	if rec.Code != http.StatusNotFound || rec.Body.String() != "ride history entry not found" {
		t.Errorf("got %d %q, want the location service response relayed", rec.Code, rec.Body.String())
	}
	if ct := rec.Header().Get("Content-Type"); ct != "text/plain" {
		t.Errorf("content type = %q", ct)
	}
}
EOF
